import requests, time, re, numpy as np, pandas as pd
import matplotlib.pyplot as plt
from scipy import stats
rng=np.random.default_rng(7)
E="https://eutils.ncbi.nlm.nih.gov/entrez/eutils/"
def fetch_cds(acc):
    for _ in range(3):
        try:
            r=requests.get(E+"efetch.fcgi",params={"db":"nuccore","id":acc,"rettype":"fasta_cds_na","retmode":"text"},timeout=50)
            if r.status_code==200 and r.text.startswith(">"): return r.text
        except Exception: pass
        time.sleep(2)
    return None
def parse(txt):
    out={}; name=None; buf=[]; hdr=""
    for line in txt.split("\n"):
        if line.startswith(">"):
            if name: out[name]=("".join(buf).upper(),hdr)
            hdr=line; m=re.search(r"\[locus_tag=([^\]]+)\]",line)
            name=m.group(1) if m else line[1:40]; buf=[]
        else: buf.append(line.strip())
    if name: out[name]=("".join(buf).upper(),hdr)
    return out
G={}
for acc in ["NC_007201.1","NC_007196.1"]:
    t=fetch_cds(acc)
    for k,v in parse(t).items(): G[k]=v

# ---- genetic code ----
B="TCAG"; CODONS=[a+b+c for a in B for b in B for c in B]
AAS="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
code={c:a for c,a in zip([a+b+c for a in "TCAG" for b in "TCAG" for c in "TCAG"],AAS)}
syn={}
for c,a in code.items(): syn.setdefault(a,[]).append(c)
DEG={a:cs for a,cs in syn.items() if len(cs)>1 and a!="*"}   # exclude Met, Trp, stops

def codons_of(s):
    s=s[:len(s)//3*3]
    cs=[s[i:i+3] for i in range(0,len(s),3)]
    return [c for c in cs if c in code and code[c]!="*"]

# ---- reference set: cytosolic ribosomal proteins (exclude mitochondrial) ----
ref=[k for k,v in G.items() if re.search(r"\b(40S|60S)\b.*ribosomal protein",v[1],re.I)
     and not re.search(r"mitochond",v[1],re.I)]
print("cytosolic ribosomal-protein reference genes:",len(ref))
print([ (k, re.search(r"\[protein=([^\]]+)\]",G[k][1]).group(1)) for k in ref ])

cnt={c:0 for c in CODONS}
for k in ref:
    for c in codons_of(G[k][0]): cnt[c]+=1
print("reference codons total:",sum(cnt.values()))

w={}
for a,cs in DEG.items():
    mx=max(cnt[c] for c in cs)
    for c in cs: w[c]= (cnt[c]/mx) if mx>0 else 1.0
for c in w:
    if w[c]<0.01: w[c]=0.01   # Sharp & Li floor

def CAI(cs):
    v=[np.log(w[c]) for c in cs if c in w]
    return float(np.exp(np.mean(v))) if v else np.nan
def GC3(cs):
    return 100*np.mean([1 if c[2] in "GC" else 0 for c in cs])
def Nc(cs):   # Wright 1990 effective number of codons
    byaa={}
    for c in cs: byaa.setdefault(code[c],[]).append(c)
    Fs={}
    for a,lst in byaa.items():
        if a not in DEG or len(lst)<2: continue
        n=len(lst); k=len(DEG[a])
        p=np.array([lst.count(c) for c in DEG[a]])/n
        F=(n*np.sum(p**2)-1)/(n-1)
        Fs.setdefault(k,[]).append(max(F,1e-6))
    nc=2.0
    for k,base in [(2,9),(3,1),(4,5),(6,3)]:
        if k in Fs: nc+= base/np.mean(Fs[k])
        else: nc+= base/ (np.mean(Fs[4]) if 4 in Fs else 0.5)
    return min(nc,61.0)

rows=[]
for k,(s,h) in G.items():
    cs=codons_of(s)
    if len(cs)<80: continue
    rows.append(dict(locus=k,n_cod=len(cs),CAI=CAI(cs),GC3=GC3(cs),Nc=Nc(cs)))
df=pd.DataFrame(rows)
print("\ngenes scored:",len(df))

TARG={"AFUA_8G07210":"erg13A","AFUA_3G10660":"erg13B"}
CTRL={"AFUA_2G03700":"hmg1","AFUA_1G11230":"hmg2","AFUA_4G06890":"cyp51A","AFUA_7G03740":"cyp51B",
      "AFUA_2G07680":"sidA","AFUA_1G17190":"sidI","AFUA_6G04740":"act1","AFUA_1G10910":"tubA"}
def boot(k,n=3000):
    cs=np.array(codons_of(G[k][0]))
    idx=rng.integers(0,len(cs),size=(n,len(cs)))
    vals=np.array([CAI(list(cs[i])) for i in idx])
    return np.percentile(vals,[2.5,97.5]), vals

print("\nCODON ADAPTATION, targets (background = 2,023 CDS on chr 3 and chr 8)")
res={}
for k,nm in TARG.items():
    r=df[df.locus==k].iloc[0]
    ci,vals=boot(k); res[nm]=vals
    pct=100*np.mean(df.CAI<r.CAI)
    print(f"  {nm:7s} CAI={r.CAI:.3f} (95% CI {ci[0]:.3f}-{ci[1]:.3f})  GC3={r.GC3:.1f}%  Nc={r.Nc:.1f}  codons={int(r.n_cod)}  CAI percentile in background = {pct:.1f}")
print(f"  reference set (cytosolic ribosomal proteins) mean CAI = {df[df.locus.isin(ref)].CAI.mean():.3f}")
print(f"  background mean CAI = {df.CAI.mean():.3f}, sd = {df.CAI.std():.3f}")

d=res['erg13B']-res['erg13A']
p_boot=2*min(np.mean(d<=0),np.mean(d>=0)); p_boot=max(p_boot,1/3000)
print(f"\n  erg13B minus erg13A CAI = {df[df.locus=='AFUA_3G10660'].CAI.iloc[0]-df[df.locus=='AFUA_8G07210'].CAI.iloc[0]:+.4f}")
print(f"  paired bootstrap 95% CI of difference: {np.percentile(d,2.5):+.4f} to {np.percentile(d,97.5):+.4f}, two-sided p = {p_boot:.4f}")
print(f"  difference in units of background sd: {(df[df.locus=='AFUA_3G10660'].CAI.iloc[0]-df[df.locus=='AFUA_8G07210'].CAI.iloc[0])/df.CAI.std():+.2f}")

print("\nControls:")
for k,nm in CTRL.items():
    if k in set(df.locus):
        r=df[df.locus==k].iloc[0]
        print(f"  {nm:7s} CAI={r.CAI:.3f}  GC3={r.GC3:.1f}%  Nc={r.Nc:.1f}  percentile={100*np.mean(df.CAI<r.CAI):.1f}")
    else: print(f"  {nm:7s} not on chr3/chr8, not scored")

out=df.copy(); out["label"]=out.locus.map({**TARG,**CTRL}).fillna("")
out.to_csv("erg13_codon_usage.csv",index=False)

fig,ax=plt.subplots(1,3,figsize=(17,5))
a=ax[0]
a.hist(df.CAI,bins=60,color="#cccccc",edgecolor="none")
for nm,k,c in [("erg13A","AFUA_8G07210","#c0504d"),("erg13B","AFUA_3G10660","#4f81bd")]:
    v=df[df.locus==k].CAI.iloc[0]; a.axvline(v,color=c,lw=2); a.text(v,a.get_ylim()[1]*0.9,nm,color=c,rotation=90,va="top",ha="right",fontsize=9)
a.axvline(df[df.locus.isin(ref)].CAI.mean(),color="green",ls="--",lw=1.5)
a.text(df[df.locus.isin(ref)].CAI.mean(),a.get_ylim()[1]*0.55,"ribosomal mean",color="green",rotation=90,va="top",ha="right",fontsize=8)
a.set_xlabel("codon adaptation index"); a.set_ylabel("genes"); a.set_title("CAI of both paralogues against 2,023 chr3 + chr8 genes",fontsize=10)
a=ax[1]
a.hist(d,bins=60,color="#9bbb59",edgecolor="none")
a.axvline(0,color="k",lw=1.5)
a.set_xlabel("CAI(erg13B) minus CAI(erg13A), paired codon bootstrap")
a.set_ylabel("bootstrap replicates"); a.set_title(f"Difference excludes zero, p = {p_boot:.3f}",fontsize=10)
a=ax[2]
a.scatter(df.GC3,df.Nc,s=4,color="#dddddd")
for nm,k,c in [("erg13A","AFUA_8G07210","#c0504d"),("erg13B","AFUA_3G10660","#4f81bd")]:
    r=df[df.locus==k].iloc[0]; a.scatter(r.GC3,r.Nc,s=90,color=c,zorder=5,edgecolor="k"); a.annotate(nm,(r.GC3,r.Nc),xytext=(6,6),textcoords="offset points",fontsize=10,color=c)
for k,nm in CTRL.items():
    if k in set(df.locus):
        r=df[df.locus==k].iloc[0]; a.scatter(r.GC3,r.Nc,s=40,color="#555555",zorder=4); a.annotate(nm,(r.GC3,r.Nc),xytext=(4,-10),textcoords="offset points",fontsize=7,color="#555555")
a.set_xlabel("GC at third codon position (%)"); a.set_ylabel("effective number of codons, Nc")
a.set_title("Wright plot, lower Nc means stronger codon bias",fontsize=10)
plt.tight_layout(); plt.show()
